    auto calculateBoard = [](long long x, long long y) -> long long {
        if (x > y) std::swap(x, y);
        long long totalCells = x * y;
        if (x % 2 == 1 && y % 2 == 1) totalCells--;
        if (x == 1) {
            long long fullSets = (x * y) / 6 * 6;
            long long leftover = (x * y) % 6;
            if (leftover == 4) fullSets += 2;
            if (leftover == 5) fullSets += 4;
            return fullSets;
        }
        if (x == 2 && y == 2) return 0;
        if (x == 2 && y == 3) return 4;
        if (x == 2 && y == 7) return 12;
